"""Authored v6.12 CPU entry and memory mechanisms; no generated fallback text."""
def register(topic, q, detail):
    topic('Rseq·CPU 이동과 재시작 구간','CPU·아키텍처','kernel/rseq.c','rseq_ip_fixup',
      'CPU별 데이터를 빠르게 갱신할 때 계산 중 CPU가 바뀌면 잘못된 CPU의 상태를 수정할 수 있습니다.',
      '사용자 공간이 rseq_cs에 시작 주소·커밋 뒤 경계·중단 주소를 등록합니다. 선점·신호·CPU 이동 뒤 커널은 저장된 명령 주소가 구간 안인지 검사하고 필요한 경우 abort_ip로 복귀 위치를 바꿉니다. 성공 커밋 이전의 계산을 재시작하는 협력 규약입니다.',
      '지원 여부를 확인하고 검토된 라이브러리의 rseq 등록·구간 규약을 사용합니다. 중단 가능한 구간에서 이미 외부에 공개한 여러 변경을 커널이 자동 취소한다고 가정하지 않습니다.',
      'rseq_ip_fixup의 in_rseq_cs, rseq_need_restart, instruction_pointer_set을 연결하세요.',
      q('rseq 구간이 중단되면 커널이 모든 사용자 메모리 쓰기를 되돌리는가?','아니다. 중단 주소로 복귀시키는 규약이다','모든 메모리 쓰기를 자동 취소한다','명령 주소를 바꾸는 것과 이미 발생한 메모리 변경을 롤백하는 것은 다릅니다. 커밋 전의 쓰기 규칙을 지켜야 합니다.'),
      q('명령 주소가 등록된 rseq 구간 밖이면 재시작 점으로 무조건 이동하는가?','아니다. 구간 밖에서는 rseq_cs를 지우는 경로가 있다','항상 abort_ip로 이동한다','in_rseq_cs가 거짓이면 clear_rseq_cs로 돌아갑니다. 구간 경계 검사가 복귀 주소 변경의 전제입니다.'),
      details=[detail('커밋을 한 번의 공개로 설계','예를 들어 CPU별 큐의 끝 위치를 읽고 새 값을 계산한 뒤 마지막 저장을 커밋으로 둡니다. 중간 계산이 중단되면 다시 CPU와 위치를 읽습니다. 구간 내부의 모든 명령이 하드웨어 트랜잭션으로 바뀌는 것은 아닙니다.'),detail('레지스터 저장 자료구조','pt_regs는 사용자 공간으로 돌아갈 레지스터 상태를 담습니다. instruction_pointer_set은 이 상태의 명령 주소를 바꿉니다. rseq_cs는 사용자가 제공하므로 주소·정렬·구간 값을 검증하고 읽기 실패도 처리합니다.')])

    topic('Membarrier·프로세스 스레드 사이 배리어','CPU·아키텍처','kernel/sched/membarrier.c','SYSCALL_DEFINE3(membarrier,',
      '공유 자료구조를 갱신한 뒤 다른 스레드의 메모리 접근 순서까지 고려해야 하는 알고리즘이 있습니다.',
      'membarrier는 명령별로 대상 CPU·프로세스 범위를 정해 배리어가 수행되도록 합니다. expedited 경로는 등록 상태와 CPU 마스크를 확인합니다. 메모리 순서를 보장하는 배리어와 스레드가 같은 자원에 동시에 들어가지 못하게 하는 상호 배제는 다릅니다.',
      'QUERY로 명령 지원을 조회하고 PRIVATE_EXPEDITED 같은 명령의 사전 등록을 따릅니다. 공유 변수는 필요한 원자 연산·동기화 규약과 함께 설계하며 membarrier 호출만으로 데이터 경쟁이 사라진다고 판단하지 않습니다.',
      'SYSCALL_DEFINE3의 cmd·flags·cpu_id와 PRIVATE_EXPEDITED 등록 검사를 읽으세요.',
      q('membarrier를 호출하면 두 스레드가 임계 구역에 동시에 들어가지 못하는가?','배리어만으로 상호 배제를 제공하지 않는다','자동으로 mutex를 획득한다','배리어는 순서 보장이고 mutex는 진입을 제한합니다. 역할을 구분해야 올바른 공유 자료구조가 됩니다.'),
      q('명령 지원 여부를 먼저 알아보는 membarrier 명령은?','MEMBARRIER_CMD_QUERY','어떤 flags든 임의로 설정','QUERY는 지원 명령의 비트 마스크를 돌려줍니다. 지원과 사전 등록을 확인한 뒤 해당 명령을 사용합니다.'),
      details=[detail('누가 배리어를 수행하는가','호출한 스레드 자신의 배리어 하나와 다른 CPU에서 실행 중인 대상 스레드까지 배리어를 수행시키는 것은 범위가 다릅니다. 원격 CPU 호출과 스케줄링 경계의 규약을 함께 보세요.'),detail('Flags의 오류 경로','v6.12는 cmd·flags·cpu_id의 세 인수를 받습니다. RSEQ 명령의 CPU 지정 예외와 일반 명령의 flags=0 검사를 구분합니다. 오래된 두 인수 설명을 그대로 쓰면 이 버전의 소스와 맞지 않습니다.')])

    topic('RISC-V·SBI와 권한 전환','CPU·아키텍처','arch/riscv/include/asm/sbi.h','sbi_ecall',
      '커널이 CPU의 모든 하드웨어 서비스를 직접 처리하는지와 펌웨어에 요청하는 경계를 알아야 합니다.',
      'Supervisor 모드 Linux는 SBI 확장·함수 ID와 인수를 정해 ecall로 실행 환경에 서비스를 요청합니다. sbiret의 error와 value를 구분합니다. Machine 모드 펌웨어나 가상화 실행 환경이 서비스할 수 있어 SBI를 특정 펌웨어 구현 하나와 동일시할 수 없습니다.',
      '커널에서는 sbi_set_timer 등 해당 서비스 래퍼를 따라갑니다. 확장 지원 여부와 반환 오류를 확인합니다. 일반 사용자 프로그램의 시스템 콜과 커널의 SBI 호출은 서로 다른 권한 경계입니다.',
      'sbi_ecall 매크로와 __sbi_ecall 선언을 보고 arch/riscv/kernel/sbi.c의 서비스 래퍼를 연결하세요.',
      q('SBI 요청에서 확장 ID와 함수 ID를 구분하는 이유는?','서비스 종류와 그 안의 동작을 지정한다','두 ID는 항상 무시된다','확장과 함수가 요청할 서비스의 의미를 정합니다. 매크로는 이 ID와 인수를 실제 호출 인수 순서로 전달합니다.'),
      q('사용자 프로그램의 Linux 시스템 콜과 SBI ecall은 같은 인터페이스인가?','서로 다른 권한 경계와 호출 규약이다','완전히 같은 함수 목록이다','사용자→커널의 시스템 콜과 Supervisor 커널→실행 환경의 SBI 서비스는 제공자와 규약이 다릅니다.'),
      details=[detail('레지스터 호출 규약','SBI는 인수 레지스터와 확장·함수 ID를 사용합니다. C 매크로에서 e,f가 마지막 두 인수로 옮겨지는 것을 확인하세요. 값을 함수에 넘기는 C 표현과 실제 ecall 명령을 수행하는 어셈블리 경계를 구분합니다.'),detail('타이머를 설정한 뒤의 흐름','커널이 다음 타이머 시점을 요청하면 실행 환경이 하드웨어를 설정합니다. 이후 타이머 이벤트와 커널 인터럽트 처리까지 연결해야 주기적 스케줄링의 전체 경로가 됩니다. 요청 호출 자체가 스케줄러를 즉시 실행하는 것은 아닙니다.')])

    topic('ARM64·예외 레벨과 진입','CPU·아키텍처','arch/arm64/kernel/entry-common.c','el0_svc',
      '사용자 코드가 특권이 필요한 일을 요청할 때 레지스터와 실행 상태를 안전하게 전환해야 합니다.',
      '일반 사용자 실행 EL0에서 SVC 예외가 발생하면 커널 EL1의 예외 진입 경로로 넘어갑니다. 저장된 pt_regs를 가지고 사용자 상태에서 나오는 처리, syscall dispatch, 사용자 복귀 처리를 수행합니다. EL2·EL3의 존재가 모든 시스템 콜이 그 레벨까지 지나간다는 뜻은 아닙니다.',
      'el0t_64_sync_handler에서 ESR 예외 원인을 구분한 뒤 el0_svc로 들어가는 흐름을 읽습니다. 레지스터 저장 어셈블리와 C 처리 함수, syscall 번호에 따른 dispatch를 연결합니다.',
      'el0_svc의 enter_from_user_mode→do_el0_svc→exit_to_user_mode를 순서대로 찾으세요.',
      q('SVC 시스템 콜이 ARM64의 EL0 사용자 실행에서 일반적으로 진입하는 커널 레벨은?','EL1','모든 경우 EL3','일반 Linux 사용자 실행과 커널 실행의 경계는 EL0와 EL1입니다. 상위 레벨은 별도 역할과 구성이 있습니다.'),
      q('동기 예외 처리기가 ESR의 원인을 구분하는 이유는?','SVC·Fault 등 서로 다른 예외를 처리하기 위해','모든 예외가 같은 syscall이기 때문에','같은 진입 벡터에서도 예외 원인이 다를 수 있습니다. ESR의 EC 분기로 해당 처리기를 고릅니다.'),
      details=[detail('함수 호출과 예외의 차이','일반 C 함수 호출은 현재 권한으로 실행됩니다. 예외는 CPU가 정해진 진입 주소로 가며 상태를 저장하는 권한 전환입니다. C의 el0_svc만 읽으면 이전 어셈블리 저장 과정이 보이지 않으므로 entry.S도 연결해야 합니다.'),detail('복귀 전 처리','커널에서 시스템 콜 결과를 넣은 뒤 신호·재스케줄링 등 사용자 복귀 전에 할 일을 확인합니다. 단순히 C 함수가 return했다고 곧바로 사용자 프로그램 다음 줄을 실행하는 것은 아닙니다.')])

    topic('x86·시스템 콜 진입과 복귀','CPU·아키텍처','arch/x86/entry/common.c','do_syscall_64',
      '프로그램의 시스템 콜 요청이 커널 함수 선택과 결과 반환으로 이어지는 경로를 알아야 합니다.',
      'x86-64 진입 어셈블리가 레지스터 상태를 준비하면 do_syscall_64가 진입 처리 후 syscall 번호와 ABI에 맞게 dispatch합니다. 존재하지 않는 호출은 ENOSYS 경로로 처리합니다. 복귀 상태가 SYSRET 조건에 맞는지 검사해 필요하면 IRET 경로를 택합니다.',
      'entry_64.S와 do_syscall_64, do_syscall_x64, 실제 __x64_sys_* 처리기를 연결합니다. libc 함수 이름과 시스템 콜 번호가 일대일이라고 가정하지 말고 syscall 테이블과 ABI를 확인합니다.',
      'do_syscall_64의 regs->ax 결과와 SYSRET 안전 조건 주석을 읽으세요.',
      q('do_syscall_64는 복귀 시 항상 SYSRET만 사용하는가?','조건에 맞지 않으면 IRET 경로가 필요하다','상태와 무관하게 항상 SYSRET이다','소스는 레지스터 상태의 SYSRET 적합성을 검사합니다. 더 일반적인 IRET 복귀가 필요한 경우가 있습니다.'),
      q('유효하지 않은 시스템 콜 번호의 처리 목표는?','미구현 호출 오류를 반환한다','임의의 커널 함수 주소를 실행한다','검사된 dispatch에서 벗어난 번호는 ni_syscall 경로로 처리됩니다. 번호를 무검증 함수 주소로 쓰지 않습니다.'),
      details=[detail('저장 상태와 반환값','pt_regs의 ax는 요청 번호·반환값과 관계됩니다. 사용자 진입 당시의 레지스터와 처리 뒤 복귀 상태를 구분하세요. errno로 보이는 사용자 오류는 libc 변환과 커널의 음수 오류 규약까지 연결해야 합니다.'),detail('복귀 경로 조건','SYSRET은 빠르지만 허용되는 사용자 주소·flags·segment 등의 제약이 있습니다. 안전한 복귀 조건을 확인해야 하므로 성능만 보고 두 경로를 서로 바꿀 수 없습니다.')])

    topic('Cache Coherency·캐시 라인 공유','CPU·아키텍처','kernel/locking/qspinlock.c','queued_spin_lock_slowpath',
      '여러 CPU가 같은 메모리를 수정할 때 캐시 라인의 이동 비용이 동기화 성능을 좌우합니다.',
      '캐시 일관성은 같은 라인의 쓰기가 다른 CPU 관찰과 일관되도록 관리하는 하드웨어 규약입니다. qspinlock은 경쟁이 커지면 MCS 노드 기반 큐를 활용해 모두가 한 공유 word만 반복 수정하는 부담을 줄입니다. 캐시 일관성과 서로 다른 주소 사이 메모리 순서 보장은 구분해야 합니다.',
      '공유 변수의 lock과 원자 연산을 규약대로 사용합니다. 다른 변수라도 한 캐시 라인에 있으면 false sharing이 생길 수 있어 배치·padding·CPU별 데이터를 측정하며 선택합니다.',
      'qspinlock의 lock·pending·tail 상태와 mcs_spinlock 노드를 찾으세요.',
      q('서로 다른 카운터가 같은 캐시 라인에 있어 경쟁 비용이 커지는 현상은?','False sharing','두 변수의 값이 자동으로 같아지는 것','논리적으로 다른 변수라도 캐시 관리 단위가 같으면 각 CPU의 쓰기가 라인 소유권 이동을 유발할 수 있습니다.'),
      q('캐시 일관성만 있으면 모든 다른 주소의 읽기·쓰기 순서까지 자동 보장되는가?','그렇지 않다. 메모리 순서 규약이 따로 필요하다','모든 프로그램 순서가 자동 보장된다','동일 라인의 일관성과 서로 다른 접근의 순서 보장은 다른 성질입니다. 필요한 barrier와 lock 규약을 따릅니다.'),
      details=[detail('MCS 큐의 이유','대기자를 연결해 자기 노드의 상태를 기다리게 하고 앞 대기자가 다음 노드에 넘깁니다. 모든 CPU가 하나의 lock 변수를 계속 교환하려는 접근을 줄입니다. 노드 수명·큐 연결·해제 순서도 정확해야 합니다.'),detail('측정 가능한 비용','락의 임계 구역이 짧아도 CPU 수·NUMA 거리·라인 이동으로 대기 비용이 커집니다. 처리량과 대기 시간, cache miss 등의 계측을 함께 봅니다. 임의의 padding이 항상 이득인지는 측정해야 합니다.')])

    topic('NUMA 정책·노드 선택과 mbind','메모리','mm/mempolicy.c','do_mbind',
      'CPU가 어느 메모리 노드에 접근하는지에 따라 지연과 대역폭이 달라져 배치 정책이 필요합니다.',
      'NUMA는 메모리 노드별 접근 거리가 다른 구조입니다. mbind는 주소 범위에 메모리 정책을 설정하며 bind·preferred·interleave는 노드 선택 방식이 다릅니다. 이미 존재하는 페이지를 이동할지는 별도 flags·권한·이동 가능성에 따릅니다.',
      'Linux에서 numactl --hardware로 토폴로지를 보고 정책과 CPU affinity를 함께 검토합니다. mbind의 페이지 정렬 범위·노드 마스크·mode·이동 flags를 확인하고 반환 오류를 처리합니다.',
      'do_mbind의 start 정렬 검사, 정책 생성, pagelist와 이동 결과를 읽으세요.',
      q('mbind로 정책만 지정하면 기존 페이지도 언제나 전부 이동하는가?','아니다. 이동 flags와 이동 가능성 등을 확인해야 한다','기존 페이지는 항상 즉시 전부 이동한다','정책 설정과 기존 페이지 이주는 구별됩니다. 이동 요청·권한·페이지 상태에 따라 실패하거나 일부만 이동할 수 있습니다.'),
      q('주소 범위 정책과 CPU affinity를 같이 고려하는 이유는?','실행 CPU와 메모리 노드의 거리가 접근 비용에 영향을 주기 때문','CPU 위치는 메모리 접근과 무관하기 때문','정책으로 고른 메모리 노드와 실제 실행 CPU의 위치가 다르면 원격 접근 비용이 생길 수 있습니다.'),
      details=[detail('정책별 선택','Bind는 허용 노드 집합 안에서 할당을 제한하고 preferred는 선호 노드를 두며 interleave는 할당을 여러 노드로 분산합니다. cpuset 등 추가 제한과 예외까지 읽어야 실제 허용 집합을 알 수 있습니다.'),detail('범위와 VMA','정책 대상은 주소 구간이므로 VMA를 순회하고 필요하면 나눕니다. nodemask_t는 숫자 하나가 아니라 노드 집합의 비트맵입니다. 페이지 이동 목록은 정책 객체와 역할이 다릅니다.')])

    topic('DAMON·접근 샘플링과 구간 조절','메모리','mm/damon/core.c','damon_merge_regions_of',
      '모든 메모리 접근을 하나씩 기록하면 관찰 비용이 커져 적은 샘플로 사용 경향을 파악해야 합니다.',
      'DAMON은 주소 공간을 구간으로 나누어 접근을 샘플링하고 접근 빈도가 비슷한 인접 구간을 합칩니다. 합칠 때 구간 크기를 가중치로 접근 수와 age를 평균합니다. 빈도가 달라지면 구간 조절을 통해 관찰 정확도와 비용을 조절합니다.',
      '지원 커널의 DAMON 관리 인터페이스에서 대상·샘플링·집계 간격과 구간 수를 설정합니다. 샘플 기반 수치를 모든 실제 접근의 정확한 횟수로 해석하지 않습니다. 적용 전 관찰 비용과 구간 단위를 확인합니다.',
      'damon_merge_regions_of의 인접성·빈도 차·크기 제한과 damon_merge_two_regions의 가중 평균을 찾으세요.',
      q('크기 2인 구간의 접근 수 4와 크기 6인 구간의 접근 수 8을 합치면 가중 평균은?','7','6','(4×2+8×6)/(2+6)=56/8=7입니다. 단순히 두 수의 평균 6을 사용하지 않습니다.'),
      q('접근 빈도가 비슷해도 주소가 떨어진 두 구간을 이 병합 함수가 바로 합치는가?','인접 구간인지도 확인한다','거리와 관계없이 항상 합친다','prev->ar.end==r->ar.start 조건이 있어 주소가 맞닿아야 합니다. 빈도 차와 합친 크기 제한도 함께 검사합니다.'),
      details=[detail('구간 자료구조','damon_region의 ar.start·ar.end는 범위, nr_accesses는 관찰 수, age는 경향이 유지된 정도입니다. 안전 순회 매크로는 현재 구간이 병합으로 제거될 가능성을 고려합니다.'),detail('Age와 정밀도','이전 집계와 접근 수 차가 threshold를 넘으면 age를 0으로 되돌리고 아니면 증가시킵니다. 지역 크기와 최대 구간 수는 정밀도·관리 비용의 절충입니다. 샘플 간격을 줄인다고 무조건 최선인 것은 아닙니다.')])

    topic('KSM·동일 페이지 병합','메모리','mm/ksm.c','cmp_and_merge_page',
      '서로 다른 프로세스의 동일한 익명 페이지를 공유하면 메모리를 줄일 수 있지만 쓰기 분리가 필요합니다.',
      'KSM은 병합을 허용한 익명 페이지를 스캔해 내용이 같은 페이지를 찾습니다. checksum은 후보 안정성 검사에 쓰이며 최종 동일성은 내용을 비교해야 합니다. Stable·unstable 트리와 역매핑을 사용하고 공유 페이지의 쓰기는 COW로 분리합니다.',
      'MADV_MERGEABLE 등 대상의 병합 허용과 KSM 설정을 확인합니다. 스캔 비용·COW 비용·보안 경계·NUMA 배치를 고려합니다. 단순히 해시값이 같다고 다른 내용을 합치지 않습니다.',
      'cmp_and_merge_page의 checksum, stable_tree_search, unstable_tree_search_insert와 병합 실패 경로를 읽으세요.',
      q('KSM에서 checksum만 같으면 페이지 내용도 무조건 동일한가?','아니다. 실제 내용 비교가 필요하다','해시 충돌이 불가능하므로 동일하다','유한한 checksum에는 충돌 가능성이 있습니다. 병합은 실제 내용과 쓰기 보호 등 조건을 확인해야 합니다.'),
      q('병합된 페이지를 한 프로세스가 수정할 때 다른 프로세스 내용도 바뀌어야 하는가?','COW로 분리해 각 프로세스 의미를 보존한다','모든 프로세스에 쓰기를 그대로 공유한다','내용이 같아서 절약한 익명 페이지는 공동 수정 자료구조가 아닙니다. 쓰기 시 사본을 만들어 독립성을 유지합니다.'),
      details=[detail('Stable·Unstable 트리','Stable 트리는 이미 병합된 페이지를 추적하고 unstable 트리는 스캔 중 후보를 비교하는 데 사용합니다. 페이지 내용은 사용자 쓰기로 바뀔 수 있어 트리 유지와 재검증이 필요합니다.'),detail('역매핑의 필요','한 공유 페이지를 여러 가상 주소가 참조하므로 모든 매핑과 쓰기 보호를 관리해야 합니다. rmap_item과 stable_node는 데이터 비교뿐 아니라 수명·매핑·이동을 연결합니다.')])

    topic('Userfaultfd·사용자 공간의 Fault 처리','메모리','fs/userfaultfd.c','handle_userfault',
      '페이지 내용의 준비를 사용자 관리자가 맡으면 지연 로딩이나 가상 머신 메모리 이동을 구현할 수 있습니다.',
      '등록 범위의 특정 Fault를 커널이 userfaultfd 이벤트로 전하고 faulting thread를 대기시킵니다. 별도 관리 스레드는 이벤트를 읽고 UFFDIO_COPY·ZEROPAGE 등 지원 연산으로 페이지를 준비합니다. 해결 후 대기자가 재개하며 모드별 지원 범위를 확인해야 합니다.',
      'API 협상→주소 범위 등록→이벤트 루프→해결 ioctl 순서로 사용합니다. 처리 스레드도 같은 미해결 페이지를 요구하면 교착할 수 있어 관리 버퍼와 스레드의 의존성을 설계합니다. 권한·커널 설정 차이도 확인합니다.',
      'handle_userfault의 ctx, wait_queue, reason과 등록 모드 검사를 읽으세요.',
      q('Fault를 처리할 유일한 관리 스레드가 같은 미해결 페이지를 읽으면 어떤 문제가 생길 수 있는가?','스스로 해결 이벤트를 기다리는 교착','모든 페이지가 자동으로 복제된다','관리 스레드도 멈추면 해결할 실행 주체가 없어질 수 있습니다. 관리 경로의 메모리 의존성을 피해야 합니다.'),
      q('Userfaultfd 이벤트를 읽기만 하면 페이지 내용 준비까지 완료되는가?','지원되는 해결 ioctl 등으로 Fault를 해결해야 한다','이벤트 조회만으로 원하는 내용이 생긴다','이벤트 통지와 페이지 공급·깨우기는 별도 단계입니다. 관리자가 적합한 해결 연산과 오류 처리를 수행합니다.'),
      details=[detail('통지와 대기 자료구조','userfaultfd_ctx가 등록과 이벤트 상태를 관리하고 userfaultfd_wait_queue가 대기자를 연결합니다. 커널은 mmap 관련 lock과 대기 상태를 규약에 맞게 조정해야 합니다.'),detail('모드 구분','Missing 페이지, minor fault, write protection 지원은 매핑 종류와 기능 협상에 따라 다릅니다. 모든 매핑의 모든 Fault가 사용자에게 전달된다는 설명은 부정확합니다. 조회된 features와 ioctl 지원을 따릅니다.')])

    topic('Memory Hotplug·메모리 온라인과 오프라인','메모리','mm/memory_hotplug.c','add_memory_resource',
      '실행 중 추가된 물리 메모리를 커널 관리에 등록하는 일과 실제 할당에 사용하도록 하는 일을 구분해야 합니다.',
      'Hotplug는 물리 주소 자원과 메모리 구획을 등록하고 online 단계에서 allocator가 사용할 수 있도록 합니다. Offline은 페이지를 이동·회수한 뒤 사용에서 제거합니다. 고정된 페이지·정렬·구획·노드 조건 때문에 추가나 제거가 실패할 수 있습니다.',
      '지원 환경에서 /sys/devices/system/memory의 상태를 조회합니다. 실제 online·offline 변경은 운영 중 메모리에 영향을 주므로 학습에서는 격리된 VM과 자원 조건을 확인합니다. 등록 성공만으로 할당 가능 상태라고 판단하지 않습니다.',
      'add_memory_resource의 resource_size·range 검사와 online_pages·offline_pages를 연결하세요.',
      q('메모리 add와 online은 항상 같은 의미인가?','자원 등록과 allocator 사용 가능 전환을 구분한다','등록되면 조건 없이 모두 사용 가능하다','추가된 메모리가 online되어야 일반 할당에 사용됩니다. 시스템의 자동 online 정책 유무도 구분합니다.'),
      q('이동할 수 없는 pin 페이지가 있으면 offline은 항상 성공하는가?','제거 조건을 만족하지 못해 실패할 수 있다','모든 pin을 강제로 무시한다','사용 중인 물리 페이지를 안전하게 비우지 못하면 제거할 수 없습니다. 이동 가능성과 참조 수명 검사가 필요합니다.'),
      details=[detail('주소 자원과 Node','resource는 물리 주소 시작·끝을 포함하고 nid는 NUMA 노드와 관련됩니다. size를 inclusive 자원 범위에서 얻는 resource_size와 요청 정렬 검사에 주의하세요.'),detail('실패 처리','범위 검사·노드 준비·arch 메모리 등록은 실패할 수 있습니다. 부분적으로 마련한 자원을 해제하는 경로를 성공 경로와 함께 읽어야 다음 시도가 잘못된 상태를 보지 않습니다.')])

    topic('Memblock·초기 부팅 메모리 할당','메모리','mm/memblock.c','memblock_alloc_range_nid',
      'Buddy와 slab allocator가 준비되기 전에도 커널은 페이지 테이블과 초기 자료구조의 공간이 필요합니다.',
      'Memblock은 사용 가능한 물리 메모리와 예약 영역을 구간 목록으로 관리합니다. 크기·정렬·주소 범위·노드 조건에 맞는 빈 구간을 찾고 예약해 중복 할당을 막습니다. 일반 실행 시 kmalloc의 동작과 초기 부팅의 물리 주소 할당은 구분합니다.',
      '초기 부팅 코드에서 memblock API의 물리 주소 반환과 가상 주소 반환을 구분합니다. 범위·정렬·노드 fallback·실패값을 확인합니다. slab 준비 이후 경고 경로가 있다는 사실은 일반 코드에서 memblock을 써도 된다는 의미가 아닙니다.',
      'memblock_alloc_range_nid의 find_in_range_node→memblock_reserve와 exact_nid 분기를 읽으세요.',
      q('Memblock에서 빈 주소를 찾기만 하고 예약하지 않으면 어떤 문제가 생기는가?','다음 할당이 같은 영역을 다시 선택할 수 있다','메모리가 자동으로 영구 보호된다','검색과 예약은 별도입니다. 예약 목록에 반영해야 해당 공간이 다른 초기 할당과 겹치지 않습니다.'),
      q('exact_nid=false이고 요청 노드에서 실패하면 어떤 경로가 가능한가?','다른 노드를 대상으로 다시 찾는 fallback','반드시 첫 노드의 메모리를 무한히 기다린다','소스는 NUMA_NO_NODE 검색을 허용합니다. exact_nid와 노드 유효성 조건이 fallback 여부를 정합니다.'),
      details=[detail('정렬 계산','빈 범위 시작이 0x1003이고 4096바이트 정렬이 필요하면 다음 후보는 0x2000입니다. 정렬해 올린 뒤 크기까지 범위 안에 들어가야 합니다. 시작 주소만 유효하다고 할당할 수 없습니다.'),detail('부팅 단계 인계','초기 예약 영역과 가용 영역을 바탕으로 일반 페이지 allocator에 메모리를 넘깁니다. memblock_free_all 등 이후 수명과 초기 전용 __init 표시를 함께 봅니다. 초기 메타데이터의 수명도 무한하지 않습니다.')])

    topic('Zram·압축 RAM 블록 장치','메모리','drivers/block/zram/zram_drv.c','zram_bvec_write',
      'RAM 안의 블록 내용을 압축해 swap 등에 쓸 수 있지만 압축률과 CPU 비용을 고려해야 합니다.',
      'Zram은 블록 요청의 페이지를 압축해 메모리에 저장하고 읽을 때 복원합니다. 부분 페이지 쓰기는 기존 전체 페이지를 읽고 변경분을 합쳐 다시 저장합니다. 압축하기 어려운 데이터·같은 값 페이지 등은 별도 처리하며 논리 디스크 크기와 실제 RAM 사용량은 다릅니다.',
      'Linux에서 /sys/block/zram0의 압축 알고리즘·disksize·mm_stat 등을 조회합니다. 설정과 swap 활성화는 별도 단계이며 메모리 사용 통계를 확인합니다. 압축률을 가정해 RAM이 무한히 늘어난다고 계산하지 않습니다.',
      'zram_bvec_write_partial의 alloc_page→read→memcpy→write→free를 읽으세요.',
      q('4KiB 페이지의 512바이트만 바꾸면 나머지 내용을 보존하기 위한 과정은?','전체 페이지 읽기 후 변경분 합치고 다시 저장','나머지 3584바이트를 무조건 0으로 변경','부분 쓰기는 기존 전체 내용을 먼저 확보해 바뀌지 않은 바이트를 보존합니다. 임시 페이지 수명도 끝에 해제합니다.'),
      q('Zram disksize가 8GiB이면 언제나 실제 RAM 8GiB를 즉시 사용하는가?','논리 용량과 실제 압축 메모리 사용량은 다르다','항상 정확히 8GiB를 즉시 점유한다','논리 블록 공간과 저장한 데이터·압축률·메타데이터 비용에 따른 실제 사용량을 구분해야 합니다.'),
      details=[detail('슬롯과 압축 객체','페이지 인덱스별 슬롯이 저장 객체와 상태를 추적합니다. 압축 결과는 zsmalloc 같은 저장 allocator와 연결될 수 있습니다. 압축 함수만으로 블록 장치의 요청·슬롯 동기화가 완성되지 않습니다.'),detail('부분 쓰기의 비용','작은 쓰기 하나가 전체 페이지 복원·재압축과 임시 메모리 할당을 요구할 수 있습니다. alloc 실패·읽기 실패·재저장 실패를 구분하고 모든 경로에서 임시 페이지를 해제해야 합니다.')])

    topic('Page Pin·GUP와 DMA 수명','메모리','mm/gup.c','pin_user_pages',
      '장치가 사용자 페이지에 접근하는 동안 물리 페이지가 이동하거나 해제되면 데이터와 수명 문제가 생깁니다.',
      'pin_user_pages는 FOLL_PIN 규약으로 사용자 페이지를 고정하는 참조를 얻습니다. 일반 get_user_pages 참조와 DMA pin의 의미는 다릅니다. 성공 개수는 요청보다 작을 수 있으며 완료 뒤 대응 unpin이 필요합니다. Pin만으로 DMA 주소 변환·캐시 동기화가 끝나지는 않습니다.',
      '반환된 페이지 수와 오류를 확인하고 장치 접근이 끝난 뒤 unpin_user_pages 계열을 호출합니다. 장치 쓰기 결과의 dirty 처리와 DMA mapping API를 따릅니다. 장기 pin은 FOLL_LONGTERM과 허용 매핑 조건을 확인합니다.',
      'pin_user_pages의 is_valid_gup_args와 __gup_longterm_locked, unpin_user_pages_dirty_lock을 연결하세요.',
      q('10페이지 pin 요청이 6을 반환했다면 10개 포인터를 모두 유효하다고 사용할 수 있는가?','반환된 6페이지 범위만 성공으로 처리한다','요청 수 10개 모두 성공이다','요청한 개수와 실제 pin한 개수는 다를 수 있습니다. 부분 성공의 정리와 재시도 정책도 필요합니다.'),
      q('pin_user_pages 성공이 장치의 DMA 주소 매핑까지 자동 완성했다는 뜻인가?','아니다. DMA mapping과 완료 후 해제 규약이 별도다','어떤 장치든 즉시 같은 CPU 가상 주소를 쓴다','페이지 수명 유지와 장치 주소 공간·캐시 동기화는 다른 단계입니다. DMA API와 장치 완료를 연결해야 합니다.'),
      details=[detail('Get과 Pin 구분','FOLL_GET은 일반 페이지 참조이고 FOLL_PIN은 DMA 관련 고정을 추적하는 별도 규약입니다. 쓰기 되돌림·페이지 이동·장기 사용과 상호작용하므로 임의로 get/put으로 대체하지 않습니다.'),detail('해제 시점','전송을 제출한 직후 unpin하면 장치가 아직 접근 중일 수 있습니다. 장치 완료 또는 취소의 보장 뒤 DMA unmap·dirty 반영·unpin을 정해진 순서로 수행합니다. 오류 경로에서도 획득한 개수만큼 정리합니다.')])

    topic('Kmalloc·크기 클래스와 할당 플래그','메모리','mm/slub.c','__kmalloc_noprof',
      '커널의 작은 객체 할당은 물리 페이지 하나씩 할당하는 것보다 효율적인 크기별 관리를 사용합니다.',
      'kmalloc은 요청 크기와 flags에 맞는 slab cache를 고르고 객체를 할당합니다. 큰 요청은 별도 페이지 할당 경로로 갈 수 있습니다. GFP flags는 잠들 수 있는지·회수와 I/O를 허용하는지 등 문맥의 제약을 표현하며 실패와 수명 관리는 호출자 책임입니다.',
      '일반 잠들 수 있는 문맥의 GFP_KERNEL과 atomic 문맥의 제약을 구분하고 NULL을 검사합니다. 필요한 초기화는 kzalloc 등을 검토하며 사용 뒤 kfree합니다. 큰 연속 할당과 가상 연속인 vmalloc의 용도를 구분합니다.',
      '__kmalloc_noprof→__do_kmalloc_node의 크기 검사·kmalloc_slab·slab_alloc_node를 읽으세요.',
      q('spinlock을 잡아 잠들 수 없는 경로에서 GFP_KERNEL을 무조건 사용해도 되는가?','할당 문맥과 flags의 잠들기 제약을 맞춰야 한다','항상 안전하며 실패하지 않는다','GFP_KERNEL은 잠들 수 있는 회수 경로를 허용합니다. atomic 문맥에서 이를 무조건 허용할 수 없습니다.'),
      q('kmalloc으로 얻은 객체는 항상 모든 바이트가 0인가?','0 초기화는 kzalloc 등의 규약을 따로 사용한다','어떤 flags든 항상 0이다','일반 kmalloc의 내용은 0 보장이 아닙니다. 초기화 없이 값을 읽으면 잘못된 상태나 정보 노출 문제가 생길 수 있습니다.'),
      details=[detail('크기 클래스와 내부 여유','요청 100바이트가 더 큰 객체 클래스에 배치될 수 있습니다. 실제 클래스 크기와 호출자가 사용 가능한 계약 크기는 구분합니다. slab은 여러 같은 크기 객체를 페이지 안에 관리해 작은 할당 비용을 줄입니다.'),detail('Flags와 실패 처리','GFP_ATOMIC도 무조건 성공을 보장하지 않습니다. 실패하면 상태를 유지하거나 오류를 반환해야 합니다. 회수 중 재귀 I/O를 피하는 GFP_NOIO 같은 문맥 규약도 호출 경로에서 결정됩니다.')])
